script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';

await step('Điều hướng đến Báo cáo Hiệu suất làm việc -> Theo Khu Vực, Đơn vị', async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(`https://tasks.zuizui.io/${phanHe}/dashboard`, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const reportBtn = page.getByRole('button', { name: 'Báo cáo' });
  if (await reportBtn.isVisible().catch(() => false)) await reportBtn.click();
  const perfLink = page.getByRole('link', { name: 'Hiệu suất làm việc' });
  if (await perfLink.isVisible().catch(() => false)) await perfLink.click();
  const unitLink = page.getByRole('link', { name: 'Theo Khu Vực, Đơn vị' });
  await unitLink.waitFor({ timeout: 10000 });
  await unitLink.click();
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
});

await step('Kiểm tra bảng thống kê và chức năng sắp xếp', async () => {
  const txt = await page.locator('body').innerText();
  for (const col of ['Đơn vị', 'Số phiếu phát sinh', 'Số phiếu hoàn tất xử lý']) {
    assert(txt.includes(col), 'Thiếu cột trên bảng Hiệu suất: ' + col);
  }
  const sortIcon = page.locator('.table-advance__sort > svg').first();
  if (await sortIcon.isVisible().catch(() => false)) {
    await sortIcon.click();
    await page.waitForTimeout(300);
  }
});

await step('Kiểm tra bộ lọc và nút Xuất dữ liệu', async () => {
  const filterBtn = page.locator('.filter__item > svg').first();
  if (await filterBtn.isVisible().catch(() => false)) {
    await filterBtn.click();
    await page.getByRole('button', { name: 'Áp dụng' }).waitFor({ timeout: 8000 });
    await page.getByRole('button', { name: 'Áp dụng' }).click();
  }
  const exportBtn = page.getByRole('button', { name: 'Xuất dữ liệu' });
  assert(await exportBtn.isVisible().catch(() => false), 'Không thấy nút Xuất dữ liệu');
  ctx.log('Đã kiểm tra Báo cáo Hiệu suất Theo Khu Vực, Đơn vị.');
});
